import{_ as e,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Atualizar painéis da Central de Mandados ao abrir","description":"","frontmatter":{"title":"Atualizar painéis da Central de Mandados ao abrir","id":"eproc-atualizar-paineis-mandados","plataforma":"eproc","grupo":"Mandados","plano":"free","desde":"1.15.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-atualizar-paineis-mandados"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-atualizar-paineis-mandados"}],["meta",{"property":"og:title","content":"Atualizar painéis da Central de Mandados ao abrir | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-atualizar-paineis-mandados.md","filePath":"funcionalidades/eproc-atualizar-paineis-mandados.md"}'),i={name:"funcionalidades/eproc-atualizar-paineis-mandados.md"};function n(d,a,t,l,p,c){return o(),r("div",null,a[0]||(a[0]=[s('<h1 id="atualizar-paineis-da-central-de-mandados-ao-abrir" tabindex="-1">Atualizar painéis da Central de Mandados ao abrir <a class="header-anchor" href="#atualizar-paineis-da-central-de-mandados-ao-abrir" aria-label="Permalink to &quot;Atualizar painéis da Central de Mandados ao abrir&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>O Painel Gestão de Mandados abre com os números da última consulta, como mostra a linha &quot;Dados gerados em&quot; de cada painel. Para ver os números atuais, era preciso clicar no ícone de atualizar de cada um dos três painéis. Com este recurso, os três são atualizados sozinhos assim que a página abre.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, no perfil da Central de Mandados, no Painel Gestão de Mandados (a página inicial do perfil).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Entre no perfil da Central de Mandados ou abra o Painel Gestão de Mandados.</li><li>Aguarde alguns segundos: os painéis Mandados, Mandados com mensagens e Mandados aguardando cumprimento por Oficial de Justiça são atualizados um após o outro.</li><li>Confira o horário em &quot;Dados gerados em&quot;, que passa a ser o do momento em que a página abriu.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><p>Este recurso é <strong>experimental</strong>: está em testes e pode mudar. Se notar algo estranho, avise.</p><p>Só os ícones de atualizar dos cabeçalhos dos painéis são acionados; os das linhas (cada tipo de mensagem, cada oficial) continuam manuais. A atualização acontece uma vez por abertura da página.</p>',12)]))}const h=e(i,[["render",n]]);export{m as __pageData,h as default};
